 "content": "from collections import deque


def _components(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            color = grid[r][c]
            q = [(r, c)]
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.pop()
                cells.append((y, x))
                for yy, xx in ((y-1, x), (y+1, x), (y, x-1), (y, x+1)):
                    if 0 <= yy < h and 0 <= xx < w and (yy, xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy, xx))
                        q.append((yy, xx))
            comps.append({'color': color, 'cells': cells})
    return comps


def _has_enclosed_hole(cells):
    r0 = min(r for r, c in cells); r1 = max(r for r, c in cells)
    c0 = min(c for r, c in cells); c1 = max(c for r, c in cells)
    filled = {(r, c) for r, c in cells}
    seen = set()
    q = deque()
    for r in range(r0, r1 + 1):
        for c in range(c0, c1 + 1):
            if r in (r0, r1) or c in (c0, c1):
                if (r, c) not in filled and (r, c) not in seen:
                    seen.add((r, c)); q.append((r, c))
    while q:
        r, c = q.popleft()
        for rr, cc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
            if r0 <= rr <= r1 and c0 <= cc <= c1 and (rr,cc) not in filled and (rr,cc) not in seen:
                seen.add((rr,cc)); q.append((rr,cc))
    return any((r, c) not in filled and (r, c) not in seen
               for r in range(r0, r1 + 1) for c in range(c0, c1 + 1))


def transform(grid):
    h, w = len(grid), len(grid[0])
    comps = _components(grid)
    # Hollow/enclosed shapes rise; the other shapes fall. Each object moves
    # rigidly until it reaches an edge or another object's colored cells.
    for obj in comps:
        obj['dir'] = -1 if _has_enclosed_hole(obj['cells']) else 1

    while True:
        moved = False
        # Move upward objects from top to bottom, and downward ones bottom to top.
        order = sorted(range(len(comps)), key=lambda i: (
            0 if comps[i]['dir'] == -1 else 1,
            min(r for r, c in comps[i]['cells']) if comps[i]['dir'] == -1 else -max(r for r, c in comps[i]['cells'])
        ))
        for i in order:
            obj = comps[i]
            dr = obj['dir']
            others = set()
            for j, other in enumerate(comps):
                if i != j:
                    others.update(other['cells'])
            candidate = [(r + dr, c) for r, c in obj['cells']]
            if all(0 <= r < h and (r, c) not in others for r, c in candidate):
                obj['cells'] = candidate
                moved = True
        if not moved:
            break

    out = [[0 for _ in range(w)] for _ in range(h)]
    for obj in comps:
        for r, c in obj['cells']:
            out[r][c] = obj['color']
    return out
